const { siraylaIsle, tekrarDene, say, ortalama, grupla } = require('./islem.js');

async function test() {
  // tekrarDene test
  let c = 0;
  const r = await tekrarDene(async (i) => { c++; if (i < 2) throw new Error('fail'); return 'ok'; }, 3);
  console.log('tekrarDene:', r, 'calls:', c);

  // tekrarDene hata fırlatma test
  try {
    await tekrarDene(async () => { throw new Error('always fail'); }, 2);
  } catch (e) {
    console.log('tekrarDene hata:', e.message);
  }

  // say test
  console.log('say:', JSON.stringify(say(['a','b','a','c','b','a'])));

  // ortalama test
  console.log('ortalama bos:', ortalama([]));
  console.log('ortalama:', ortalama([1,2,3,4]));

  // grupla test
  console.log('grupla:', JSON.stringify(grupla([1,2,3,4,5], x => x % 2)));

  // siraylaIsle sıra testi
  const order = [];
  await siraylaIsle([1,2,3], async (x) => { await new Promise(r=>setTimeout(r,10)); order.push(x); return x*10; });
  console.log('siraylaIsle order:', order);
}
test().catch(e=>console.error(e));

